parameters.jsCode:
const body = $json.body ?? $json;
const requiredFields = ['name', 'email', 'phone', 'topic', 'message', 'submissionId'];
const missingFields = requiredFields.filter((field) => !body[field]);

if (missingFields.length > 0) {
  throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
}

if (body.consent !== true && body.consent !== 'true') {
  throw new Error('Consent is required');
}

const email = String(body.email).trim().toLowerCase();
const name = String(body.name).trim();
const [firstName, ...lastNameParts] = name.split(/\s+/);
const lastName = lastNameParts.join(' ');
const phone = String(body.phone).trim();
const preferredBranch = body.preferredBranch || 'unknown';
const source = body.source || $env.CRM_DEFAULT_SOURCE || 'webflow-contact-page';

return [{
  json: {
    provider: $env.CRM_PROVIDER || 'gencode-crm',
    submissionId: String(body.submissionId),
    source,
    receivedAt: new Date().toISOString(),
    contact: {
      name,
      firstName: firstName || name,
      lastName,
      email,
      phone,
      title: body.title || '',
      ownerType: body.ownerType || ''
    },
    enquiry: {
      topic: String(body.topic),
      message: String(body.message),
      preferredBranch,
      vehicleModel: body.vehicleModel || '',
      yearOfPurchase: body.yearOfPurchase || ''
    },
    crmPayload: {
      name: {
        firstName: firstName || name,
        lastName
      },
      emails: {
        primaryEmail: email,
        additionalEmails: []
      },
      phones: {
        primaryPhoneNumber: phone,
        primaryPhoneCountryCode: '',
        additionalPhones: []
      },
      city: preferredBranch === 'unknown' ? null : preferredBranch,
      jobTitle: `Website enquiry: ${body.topic}`
    }
  }
}];

